const rawInput = $input.first().json;
const body = rawInput.body ? rawInput.body : rawInput;

if (!body.seller_id) {
  return [{ json: { decision: 'REJECTED', reason: 'MISSING_SELLER_ID', message: 'seller_id is required.' } }];
}
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(body.seller_id)) {
  return [{ json: { decision: 'REJECTED', reason: 'INVALID_SELLER_ID_FORMAT', message: 'seller_id must be a valid UUID.' } }];
}

const HARD_BLOCK_PHRASES = ['manipulate reviews', 'boost ranking', 'bypass amazon', 'force merge', 'transfer reviews'];
const WARNING_PHRASES = ['combine reviews', 'merge reviews'];

function scanList(value, phraseList) {
  if (typeof value !== 'string') return null;
  const lower = value.toLowerCase();
  for (let i = 0; i < phraseList.length; i++) {
    if (lower.includes(phraseList[i])) return phraseList[i];
  }
  return null;
}

const sellerTexts = [];
if (body.request_text) sellerTexts.push({ field: 'request_text', value: String(body.request_text) });
if (body.proposed_theme) sellerTexts.push({ field: 'proposed_theme', value: String(body.proposed_theme) });
if (body.proposed_values && typeof body.proposed_values === 'object' && !Array.isArray(body.proposed_values)) {
  Object.keys(body.proposed_values).forEach(function(k) {
    const v = body.proposed_values[k];
    if (v !== null && v !== undefined) sellerTexts.push({ field: 'proposed_values.' + k, value: String(v) });
  });
}

let hardBlockFound = null, hardBlockField = null;
let warningFound = null, warningField = null;
for (let i = 0; i < sellerTexts.length; i++) {
  const t = sellerTexts[i];
  const hb = scanList(t.value, HARD_BLOCK_PHRASES);
  if (hb && !hardBlockFound) { hardBlockFound = hb; hardBlockField = t.field; }
  const w = scanList(t.value, WARNING_PHRASES);
  if (w && !warningFound) { warningFound = w; warningField = t.field; }
}

if (hardBlockFound) {
  return [{ json: {
    decision: 'BLOCKED',
    reason: 'REVIEW_MANIPULATION_INTENT',
    issue_code: 'REVIEW_MANIPULATION_INTENT',
    matched_phrase: hardBlockFound,
    matched_field: hardBlockField,
    message: 'This request has been permanently blocked because it contains language that suggests an intent to manipulate reviews, rankings, or Amazon\'s systems. This block cannot be removed. If you believe this is a mistake, remove the flagged language from your request and resubmit. If the block persists, contact Amazon Seller Support directly.',
    can_user_fix: false,
    can_user_override: false
  }}];
}

const errors = [];
if (!body.parent_asin) errors.push('parent_asin');
if (!body.child_asin) errors.push('child_asin');
if (!body.marketplace_id) errors.push('marketplace_id');
if (!body.proposed_values || typeof body.proposed_values !== 'object' || Array.isArray(body.proposed_values)) errors.push('proposed_values (object keyed by attribute name)');
if (!Array.isArray(body.theme_attributes) || body.theme_attributes.length === 0) errors.push('theme_attributes (non-empty array - the real Amazon attribute name(s) for the theme just chosen, e.g. ["size_name"])');
if (!body.parent_proposed_values || typeof body.parent_proposed_values !== 'object' || Array.isArray(body.parent_proposed_values)) errors.push('parent_proposed_values (object - the promoted listing\'s own value for the chosen theme)');

if (errors.length > 0) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'MISSING_REQUIRED_FIELDS',
    message: 'Missing or invalid: ' + errors.join(', ') + '.'
  }}];
}

const parentAsin = String(body.parent_asin).trim().toUpperCase();
const childAsin = String(body.child_asin).trim().toUpperCase();

if (!/^[A-Z0-9]{10}$/.test(parentAsin) || !/^[A-Z0-9]{10}$/.test(childAsin)) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'INVALID_ASIN_FORMAT',
    message: 'parent_asin and child_asin must each be a 10-character alphanumeric Amazon ASIN.'
  }}];
}

if (parentAsin === childAsin) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'CHILD_EQUALS_PARENT',
    message: 'The candidate child ASIN cannot be the parent ASIN itself.'
  }}];
}

return [{ json: {
  decision: 'VALID',
  seller_id: body.seller_id,
  parent_asin: parentAsin,
  child_asin: childAsin,
  marketplace_id: body.marketplace_id,
  proposed_values: body.proposed_values,
  proposed_theme: body.proposed_theme || null,
  theme_attributes: body.theme_attributes,
  parent_proposed_values: body.parent_proposed_values,
  request_text: body.request_text || null,
  flagged_language: warningFound ? { phrase: warningFound, field: warningField } : null
}}];

const upstream = $input.first().json;
const req = $('Validate Input').first().json;

if (!upstream || upstream.error || !upstream.asin) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'PARENT_NOT_FOUND',
    parent_asin: req.parent_asin,
    marketplace_id: req.marketplace_id,
    message: 'Amazon Catalog Items API did not return this ASIN for this marketplace.',
    upstream_raw: upstream
  }}];
}

function forMarketplace(list) {
  if (!Array.isArray(list)) return {};
  return list.find(function(e) { return e.marketplaceId === req.marketplace_id; }) || list[0] || {};
}

const summary = forMarketplace(upstream.summaries);
const ptEntry = forMarketplace(upstream.productTypes);
const relEntry = forMarketplace(upstream.relationships);
const groups = Array.isArray(relEntry.relationships) ? relEntry.relationships : [];
const variationGroup = groups.find(function(g) { return g.type === 'VARIATION'; }) || null;
const childAsins = (variationGroup && Array.isArray(variationGroup.childAsins)) ? variationGroup.childAsins : [];
const parentAsinsOfIt = (variationGroup && Array.isArray(variationGroup.parentAsins)) ? variationGroup.parentAsins : [];

if (childAsins.length > 0) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'ALREADY_A_PARENT',
    parent_asin: req.parent_asin,
    marketplace_id: req.marketplace_id,
    existing_child_count: childAsins.length,
    message: 'This ASIN is already an established parent with ' + childAsins.length + ' existing children. Use Existing Parent mode instead.'
  }}];
}

if (parentAsinsOfIt.length > 0) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'ALREADY_A_CHILD',
    parent_asin: req.parent_asin,
    marketplace_id: req.marketplace_id,
    is_child_of: parentAsinsOfIt,
    message: 'This ASIN is itself a child in another variation family. It cannot be promoted while it belongs to a different parent.'
  }}];
}

return [{ json: {
  decision: 'PARENT_CONFIRMED',
  parent_asin: req.parent_asin,
  child_asin: req.child_asin,
  marketplace_id: req.marketplace_id,
  proposed_values: req.proposed_values,
  proposed_theme: req.proposed_theme,
  parent_proposed_values: req.parent_proposed_values,
  parent: {
    brand: summary.brand || null,
    normalized_brand: (summary.brand || '').toLowerCase().trim(),
    item_name: summary.itemName || null,
    product_type: (ptEntry.productType || '').toUpperCase().trim() || null,
    category: (summary.browseClassification && summary.browseClassification.displayName) || null,
    variation_theme: req.proposed_theme || null,
    theme_attributes: req.theme_attributes,
    child_asins: [],
    child_count: 0
  }
}}];

const gate = $input.first().json;

const existing = gate.parent.child_asins;
const candidate = gate.child_asin;
const candidateInFamily = existing.indexOf(candidate) !== -1;

const all = existing.slice();
if (!candidateInFamily) all.push(candidate);

return [{ json: {
  ctx: gate,
  candidate_in_family: candidateInFamily,
  existing_child_asins: existing,
  identifiers: all.join(',')
}}];

const batch = $input.first().json;
const prep = $('Prepare Batch List').first().json;
const ctx = prep.ctx;
const parent = ctx.parent;

if (!batch || batch.error || !Array.isArray(batch.items)) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'FAMILY_FETCH_FAILED',
    message: 'The batch catalog fetch for the candidate did not return items.',
    upstream_raw: batch
  }}];
}

const mkId = ctx.marketplace_id;

function forMarketplace(list) {
  if (!Array.isArray(list)) return {};
  return list.find(function(e) { return e.marketplaceId === mkId; }) || list[0] || {};
}

function findItem(asin) {
  return batch.items.find(function(it) { return it.asin === asin; }) || null;
}

function norm(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'object') {
    // Structured attribute value (e.g. footwear_size, shirt_size): compare
    // by the object's own fields, not by JS's default String(v), which
    // collapses every structured value to the identical "[object Object]"
    // regardless of what it actually contains - confirmed as the real cause
    // of a false UNIQUE_VARIATION_COMBINATION clash between two genuinely
    // different footwear_size values (a real size 8 and a real size 9 both
    // stringified identically before this fix).
    const keys = Object.keys(v)
      .filter(function(k) { return v[k] !== null && v[k] !== undefined; })
      .sort();
    if (keys.length === 0) return null;
    return keys.map(function(k) { return k + ':' + norm(v[k]); }).join('|');
  }
  return String(v).trim().toLowerCase();
}

function getAttrValue(item, attrName) {
  if (!item || !item.attributes || !item.attributes[attrName]) return null;
  const entries = item.attributes[attrName];
  if (!Array.isArray(entries) || entries.length === 0) return null;
  const entry = entries.find(function(e) { return e.marketplaceId === mkId; }) || entries[0];
  if (!entry) return null;
  // Simple attributes (color, style, ...) wrap their real value in
  // entry.value. Structured attributes (footwear_size, shirt_size, ...)
  // have no separate "value" field in the real PTD schema at all - the
  // entry's own sibling properties (size, size_class, size_system, ...)
  // ARE the value. Confirmed directly against footwear_size's real schema.
  // Without this branch, every structured attribute silently read as null
  // here, which would make real duplicate values among EXISTING children
  // undetectable (values_incomplete would always be true for them) - a
  // separate, quieter bug than the norm() one, in the opposite direction.
  if (entry.value !== undefined) return entry.value;
  const structured = {};
  let hasFields = false;
  Object.keys(entry).forEach(function(k) {
    if (k === 'marketplaceId' || k === 'language_tag') return;
    structured[k] = entry[k];
    hasFields = true;
  });
  return hasFields ? structured : null;
}

function hasSalesRank(item) {
  if (!item || !Array.isArray(item.salesRanks)) return false;
  const entry = item.salesRanks.find(function(e) { return e.marketplaceId === mkId; }) || item.salesRanks[0];
  if (!entry) return false;
  const cls = Array.isArray(entry.classificationRanks) ? entry.classificationRanks : [];
  const grp = Array.isArray(entry.displayGroupRanks) ? entry.displayGroupRanks : [];
  return cls.length > 0 || grp.length > 0;
}

// CHANGED: themeAttrs now comes from what the seller just chose in Theme
// Selection (passed through the request), not from parent.theme_attributes -
// there is no established family yet for that to be sourced from.
const themeAttrs = parent.theme_attributes || [];
const checks = [];

const candidateItem = findItem(ctx.child_asin);
if (!candidateItem) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'CHILD_NOT_FOUND',
    child_asin: ctx.child_asin,
    marketplace_id: mkId,
    message: 'The candidate child ASIN was not returned by the Amazon catalog for this marketplace.'
  }}];
}

const candSummary = forMarketplace(candidateItem.summaries);
const candPt = forMarketplace(candidateItem.productTypes);
const candidate = {
  asin: ctx.child_asin,
  brand: candSummary.brand || null,
  normalized_brand: (candSummary.brand || '').toLowerCase().trim(),
  item_name: candSummary.itemName || null,
  product_type: (candPt.productType || '').toUpperCase().trim() || null,
  category: (candSummary.browseClassification && candSummary.browseClassification.displayName) || null
};

const existingChildren = prep.existing_child_asins.map(function(asin) {
  const item = findItem(asin);
  const ecSummary = forMarketplace(item ? item.summaries : null);
  const values = {};
  const normalizedTuple = [];
  let anyMissing = false;
  themeAttrs.forEach(function(attr) {
    const v = getAttrValue(item, attr);
    values[attr] = v;
    if (v === null) anyMissing = true;
    normalizedTuple.push(norm(v));
  });
  return {
    asin: asin,
    found_in_catalog: !!item,
    brand: ecSummary.brand || null,
    normalized_brand: ((ecSummary.brand || '').toLowerCase().trim()) || null,
    values: values,
    normalized_tuple: normalizedTuple,
    values_incomplete: anyMissing
  };
});

const proposed = {};
const proposedTuple = [];
const missingAttrs = [];
themeAttrs.forEach(function(attr) {
  const raw = ctx.proposed_values ? ctx.proposed_values[attr] : undefined;
  if (raw === undefined || raw === null || String(raw).trim() === '') {
    missingAttrs.push(attr);
    proposed[attr] = null;
    proposedTuple.push(null);
  } else {
    proposed[attr] = raw;
    proposedTuple.push(norm(raw));
  }
});

// NEW: the promoted listing's own value for the same theme, entered by the
// seller (Amazon's catalog has no attribute data for a standalone listing
// to fetch, so this can only come from the request, not from Amazon).
const parentOwnProposed = ctx.parent_proposed_values || {};
const parentOwnTuple = themeAttrs.map(function(attr) { return norm(parentOwnProposed[attr]); });
const parentOwnComplete = themeAttrs.every(function(attr) {
  const v = parentOwnProposed[attr];
  return v !== undefined && v !== null && String(v).trim() !== '';
});

// ================= CHECKS (all reported, not first-failure) =================

// 0. Review-language caution (WARNING - unchanged from wf18).
const inputStage = $('Validate Input').first().json;
if (inputStage.flagged_language) {
  checks.push({
    check: 'REVIEW_LANGUAGE_CAUTION', status: 'warning', issue_code: 'REVIEW_LANGUAGE_MENTIONED',
    matched_phrase: inputStage.flagged_language.phrase,
    matched_field: inputStage.flagged_language.field,
    message: 'Your request mentions "' + inputStage.flagged_language.phrase + '." Amazon\'s variation system legitimately combines reviews when listings become part of the same parent-child family, so this isn\'t automatically a problem - just confirm that\'s what you mean, not something that would violate Amazon\'s review policies.'
  });
}

// 1. Brand match - unchanged. parent.brand will be real here (the promoted
// listing's actual brand), so this behaves like the "normal" case in wf18,
// not the null-parent-brand fallback path.
const childBrandSet = existingChildren
  .map(function(ec) { return ec.normalized_brand; })
  .filter(function(b, i, arr) { return b && arr.indexOf(b) === i; });

let familyBrandNorm = parent.normalized_brand || null;
let familyBrandDisplay = parent.brand || null;
let familyBrandSource = 'parent_record';
if (!familyBrandNorm) {
  if (childBrandSet.length === 1) {
    familyBrandNorm = childBrandSet[0];
    const donor = existingChildren.find(function(ec) { return ec.normalized_brand === familyBrandNorm; });
    familyBrandDisplay = donor ? donor.brand : familyBrandNorm;
    familyBrandSource = 'existing_children_consensus';
  } else {
    familyBrandSource = childBrandSet.length === 0 ? 'indeterminate_no_brand_data' : 'indeterminate_children_conflict';
  }
}

if (!familyBrandNorm) {
  checks.push({
    check: 'BRAND_MATCH', status: 'manual_review', issue_code: 'BRAND_INDETERMINATE',
    family_brand_source: familyBrandSource,
    child_brand: candidate.brand,
    existing_children_brands: childBrandSet,
    message: 'The family brand could not be determined. This is not a proven mismatch - confirm manually that the candidate shares the promoted listing\'s brand before proceeding.'
  });
} else if (candidate.normalized_brand && candidate.normalized_brand === familyBrandNorm) {
  checks.push({ check: 'BRAND_MATCH', status: 'pass', family_brand: familyBrandDisplay, family_brand_source: familyBrandSource, child_brand: candidate.brand });
} else {
  checks.push({
    check: 'BRAND_MATCH', status: 'hard_block', issue_code: 'BRAND_MISMATCH',
    family_brand: familyBrandDisplay, family_brand_source: familyBrandSource, child_brand: candidate.brand,
    message: 'The candidate child brand (' + (candidate.brand || 'unknown') + ') does not match the promoted listing\'s brand (' + (familyBrandDisplay || 'unknown') + '). All items in a variation family must share the same brand.'
  });
}

// 2. Product type match - unchanged.
if (candidate.product_type && candidate.product_type === parent.product_type) {
  checks.push({ check: 'PRODUCT_TYPE_MATCH', status: 'pass', product_type: parent.product_type });
} else {
  checks.push({
    check: 'PRODUCT_TYPE_MATCH', status: 'hard_block', issue_code: 'PRODUCT_TYPE_MISMATCH',
    parent_product_type: parent.product_type, child_product_type: candidate.product_type,
    message: 'The candidate child product type (' + (candidate.product_type || 'unknown') + ') does not match the promoted listing\'s product type (' + (parent.product_type || 'unknown') + ').'
  });
}

// 3. CHANGED: theme match. There's nothing established to conflict with -
// this IS the theme being established. Always passes when a theme was
// actually chosen; the missing-theme case is caught by Validate Input already.
checks.push({ check: 'THEME_MATCH', status: 'pass', theme: parent.variation_theme, note: 'New family - theme being established now, not inherited.' });

// 4. All theme attributes provided for the CHILD (fixable).
if (missingAttrs.length === 0) {
  checks.push({ check: 'THEME_ATTRIBUTES_PROVIDED', status: 'pass', attributes: themeAttrs });
} else {
  checks.push({
    check: 'THEME_ATTRIBUTES_PROVIDED', status: 'fixable', issue_code: 'MISSING_THEME_ATTRIBUTE_VALUE',
    missing_attributes: missingAttrs,
    message: 'This theme (' + (parent.variation_theme || 'chosen theme') + ') requires a value for each of: ' + themeAttrs.join(', ') + '. Missing: ' + missingAttrs.join(', ') + '.'
  });
}

// NEW: the promoted listing's own value for the theme also needs to be
// complete - re-checked on every child call since it's foundational to the
// uniqueness check right below, not just captured once and trusted forever.
if (parentOwnComplete) {
  checks.push({ check: 'PARENT_VALUE_PROVIDED', status: 'pass', parent_values: parentOwnProposed });
} else {
  const missingParentAttrs = themeAttrs.filter(function(attr) {
    const v = parentOwnProposed[attr];
    return v === undefined || v === null || String(v).trim() === '';
  });
  checks.push({
    check: 'PARENT_VALUE_PROVIDED', status: 'fixable', issue_code: 'MISSING_PARENT_VALUE',
    missing_attributes: missingParentAttrs,
    message: 'The first listing entered (ASIN ' + ctx.parent_asin + ') needs its own value for ' + missingParentAttrs.join(', ') + ' before the others can be checked against it.'
  });
}

// 5. CHANGED: duplicate combination now checks against existing children
// (empty here) AND the parent's own value - a child can't collide with
// either. Only checkable once every value involved is actually present.
if (missingAttrs.length === 0 && parentOwnComplete) {
  const clashChild = existingChildren.find(function(ec) {
    if (ec.values_incomplete) return false;
    return ec.normalized_tuple.length === proposedTuple.length &&
      ec.normalized_tuple.every(function(v, i) { return v === proposedTuple[i]; });
  });
  const clashesParent = parentOwnTuple.length === proposedTuple.length &&
    parentOwnTuple.every(function(v, i) { return v === proposedTuple[i]; });

  if (clashChild) {
    checks.push({
      check: 'UNIQUE_VARIATION_COMBINATION', status: 'hard_block', issue_code: 'DUPLICATE_VARIATION_VALUE',
      clashes_with_asin: clashChild.asin, clashing_values: clashChild.values, proposed_values: proposed,
      message: 'The proposed combination is already used by ' + clashChild.asin + '. Each combination of ' + themeAttrs.join(' + ') + ' must be unique in the family.'
    });
  } else if (clashesParent) {
    checks.push({
      check: 'UNIQUE_VARIATION_COMBINATION', status: 'hard_block', issue_code: 'DUPLICATE_VARIATION_VALUE',
      clashes_with_asin: ctx.parent_asin, clashing_values: parentOwnProposed, proposed_values: proposed,
      message: 'The proposed combination matches the parent listing\'s own value. Each combination of ' + themeAttrs.join(' + ') + ' must be unique in the family, including the parent itself.'
    });
  } else {
    checks.push({ check: 'UNIQUE_VARIATION_COMBINATION', status: 'pass', proposed_values: proposed });
  }
} else {
  checks.push({ check: 'UNIQUE_VARIATION_COMBINATION', status: 'skipped', note: 'Cannot check uniqueness until all values (child\'s and the parent\'s own) are provided.' });
}

// 6. Candidate already in this (brand-new, so always empty) family.
if (prep.candidate_in_family) {
  checks.push({
    check: 'NOT_ALREADY_IN_FAMILY', status: 'hard_block', issue_code: 'ALREADY_IN_FAMILY',
    message: 'This ASIN is already a child of this exact parent. There is nothing to merge.'
  });
} else {
  checks.push({ check: 'NOT_ALREADY_IN_FAMILY', status: 'pass' });
}

// 7. Candidate already belongs to a DIFFERENT parent - unchanged.
const candRel = forMarketplace(candidateItem.relationships);
const candGroups = Array.isArray(candRel.relationships) ? candRel.relationships : [];
const candVar = candGroups.find(function(g) { return g.type === 'VARIATION'; }) || null;
const candParents = (candVar && Array.isArray(candVar.parentAsins)) ? candVar.parentAsins : [];
const otherParents = candParents.filter(function(p) { return p !== ctx.parent_asin; });
if (otherParents.length > 0) {
  checks.push({
    check: 'NO_EXISTING_PARENT_CONFLICT', status: 'manual_review', issue_code: 'EXISTING_PARENT_CONFLICT',
    conflicting_parents: otherParents,
    message: 'This ASIN already belongs to a different parent (' + otherParents.join(', ') + '). Amazon does not allow one ASIN in two families. Remove it from that family first, or confirm this move is deliberate.'
  });
} else if (!prep.candidate_in_family) {
  checks.push({ check: 'NO_EXISTING_PARENT_CONFLICT', status: 'pass' });
}

// 8. Generic-brand caution - unchanged.
const brandMatchPassed = checks.some(function(c) { return c.check === 'BRAND_MATCH' && c.status === 'pass'; });
if (brandMatchPassed && familyBrandNorm === 'generic') {
  checks.push({
    check: 'GENERIC_BRAND_CAUTION', status: 'warning', issue_code: 'GENERIC_BRAND_MATCH',
    corroboration: {
      family_brand_source: familyBrandSource,
      product_type_match: candidate.product_type === parent.product_type,
      parent_category: parent.category || null,
      candidate_category: candidate.category || null
    },
    message: 'Both items carry Amazon\'s placeholder brand "Generic" rather than a registered brand. The brand match passes, but "Generic" does not uniquely confirm these products share a common origin the way a registered brand does. Please confirm these are genuinely the same product family - matching product type and category are the stronger evidence here.'
  });
}

// 9. New-listing-into-established-family note - unchanged logic. Always
// resolves to the harmless 'pass' branch here, since there's no established
// family with sales history yet for the candidate to be "new" relative to.
if (!prep.candidate_in_family) {
  const rankedExisting = existingChildren.filter(function(ec) {
    return hasSalesRank(findItem(ec.asin));
  });
  const candidateRanked = hasSalesRank(candidateItem);
  if (!candidateRanked && rankedExisting.length > 0) {
    checks.push({
      check: 'NEW_LISTING_INTO_ESTABLISHED_FAMILY', status: 'info', issue_code: 'NEW_ASIN_INTO_ESTABLISHED_PARENT',
      candidate_has_sales_rank: false,
      existing_children_with_sales_rank: rankedExisting.length,
      existing_children_total: existingChildren.length,
      blocks_nothing: true,
      message: 'The candidate appears to be a newer listing joining a family with established sales history. This is not a risk signal by itself.'
    });
  } else {
    checks.push({ check: 'NEW_LISTING_INTO_ESTABLISHED_FAMILY', status: 'pass', note: candidateRanked ? 'Candidate already has sales history.' : 'No established-family signal to note - this is a brand-new family.' });
  }
}

// 10. Value formatting suggestions - unchanged logic, now works correctly
// since themeAttrs is sourced from the request, not the (empty) parent record.
const LETTER_SIZES = ['xs', 's', 'm', 'l', 'xl', 'xxl', 'xxxl', '2xl', '3xl'];
const SIZE_STANDARD_MAP = {
  'extra small': 'XS', 'x-small': 'XS', 'small': 'S', 'medium': 'M',
  'large': 'L', 'extra large': 'XL', 'extra-large': 'XL', 'x-large': 'XL',
  'xx-large': 'XXL', 'xxlarge': 'XXL', '2x large': 'XXL'
};
function classifyCase(s) {
  if (s === s.toUpperCase() && /[A-Za-z]/.test(s)) return 'upper';
  if (s === s.toLowerCase() && /[A-Za-z]/.test(s)) return 'lower';
  const words = s.split(' ');
  const isTitle = words.every(function(w) {
    return w.length > 0 && w[0] === w[0].toUpperCase() && (w.length === 1 || w.slice(1) === w.slice(1).toLowerCase());
  });
  return isTitle ? 'title' : 'mixed';
}
function toTitleCase(s) {
  return s.split(' ').map(function(w) {
    return w.length === 0 ? w : (w[0].toUpperCase() + w.slice(1).toLowerCase());
  }).join(' ');
}

const formattingSuggestions = [];
themeAttrs.forEach(function(attr) {
  const raw = proposed[attr];
  if (raw === null || raw === undefined) return;
  // Structured values (footwear_size, shirt_size, ...) don't have one
  // string representation to suggest a formatting change for - case and
  // spelling conventions apply per sub-field, not to the object as a
  // whole, and this feature was never designed for that. Skip rather than
  // silently stringify to "[object Object]" and suggest nonsense.
  if (typeof raw === 'object') return;
  const rawStr = String(raw);
  const reasons = [];
  let current = rawStr;

  const cleaned = current.trim().replace(/\s+/g, ' ');
  if (cleaned !== current) { reasons.push('whitespace_cleanup'); current = cleaned; }

  const familyValues = existingChildren
    .filter(function(ec) { return ec.found_in_catalog && ec.values && ec.values[attr] !== null && ec.values[attr] !== undefined; })
    .map(function(ec) { return String(ec.values[attr]); });
  // Include the parent's own value as a formatting-convention reference too,
  // same reasoning as including it in the uniqueness check above.
  if (parentOwnProposed[attr] !== undefined && parentOwnProposed[attr] !== null) {
    familyValues.push(String(parentOwnProposed[attr]));
  }

  const spellingMatch = familyValues.find(function(fv) { return norm(fv) === norm(current) && fv !== current; });
  if (spellingMatch) {
    reasons.push('match_family_spelling');
    current = spellingMatch;
  } else if (familyValues.length > 0) {
    const inputCase = classifyCase(current);
    if (inputCase === 'lower' || inputCase === 'upper') {
      const familyPatterns = familyValues.map(classifyCase);
      const uniform = familyPatterns.every(function(p) { return p === familyPatterns[0]; }) ? familyPatterns[0] : null;
      if (uniform && uniform !== 'mixed' && uniform !== inputCase) {
        let converted = current;
        if (uniform === 'upper') converted = current.toUpperCase();
        else if (uniform === 'lower') converted = current.toLowerCase();
        else if (uniform === 'title') converted = toTitleCase(current);
        if (converted !== current) { reasons.push('match_family_case_convention'); current = converted; }
      }
    }
    if (attr === 'size') {
      const familyAllLetterSizes = familyValues.every(function(fv) { return LETTER_SIZES.indexOf(norm(fv)) !== -1; });
      const mapped = SIZE_STANDARD_MAP[norm(current)];
      if (familyAllLetterSizes && mapped && norm(mapped) !== norm(current)) {
        reasons.push('match_family_size_convention');
        current = mapped;
      }
    }
  }

  if (current !== rawStr) {
    formattingSuggestions.push({
      attribute: attr,
      original: rawStr,
      suggested: current,
      reasons: reasons,
      note: 'Suggestion only - confirm or keep your original. Nothing is applied automatically.'
    });
  }
});

if (formattingSuggestions.length > 0) {
  checks.push({
    check: 'VALUE_FORMATTING', status: 'suggestion', issue_code: 'FORMATTING_SUGGESTIONS',
    suggestions: formattingSuggestions,
    message: 'Some proposed values could be adjusted to match this family\'s existing conventions. These are suggestions for you to confirm - they are never applied automatically and do not block anything.'
  });
} else {
  checks.push({ check: 'VALUE_FORMATTING', status: 'pass', note: 'No formatting suggestions.' });
}

// ================= DECISION =================
const hardBlocks = checks.filter(function(c) { return c.status === 'hard_block'; });
const fixable = checks.filter(function(c) { return c.status === 'fixable'; });
const manualReviews = checks.filter(function(c) { return c.status === 'manual_review'; });
const warnings = checks.filter(function(c) { return c.status === 'warning'; });
const infoNotes = checks.filter(function(c) { return c.status === 'info'; });

let decision = 'CHILD_VALID';
if (hardBlocks.length > 0) decision = 'BLOCKED';
else if (fixable.length > 0) decision = 'NEEDS_INPUT';
else if (manualReviews.length > 0) decision = 'MANUAL_REVIEW_REQUIRED';

return [{ json: {
  decision: decision,
  parent_asin: ctx.parent_asin,
  child_asin: ctx.child_asin,
  marketplace_id: mkId,
  parent: {
    brand: parent.brand,
    product_type: parent.product_type,
    variation_theme: parent.variation_theme,
    theme_attributes: themeAttrs,
    child_count: parent.child_count
  },
  candidate: candidate,
  proposed_values: proposed,
  parent_proposed_values: parentOwnProposed,
  existing_children: existingChildren,
  checks: checks,
  hard_blocks: hardBlocks,
  fixable_issues: fixable,
  manual_reviews: manualReviews,
  warnings: warnings,
  informational_notes: infoNotes,
  formatting_suggestions: formattingSuggestions
}}];

// DAY 21 FIX: chunked family fetch.
// The Catalog Items batch endpoint hard-caps at 20 identifiers - proven live
// twice with real 33-child families ("Too many 'identifiers' provided.").
// This node splits the identifier list into chunks of 20, fetches each, and
// merges the items so the validator downstream sees one combined result.
const prep = $('Prepare Batch List').first().json;
const token = $('Exchange for Access Token').first().json.access_token;
const mkId = $('Validate Input').first().json.marketplace_id;

const ids = String(prep.identifiers || '').split(',').filter(function(s) { return s.length > 0; });
const CHUNK_SIZE = 20;
const INCLUDED = 'summaries,attributes,productTypes,relationships,salesRanks';

const allItems = [];
try {
  for (let i = 0; i < ids.length; i += CHUNK_SIZE) {
    const chunk = ids.slice(i, i + CHUNK_SIZE);
    const url = 'https://sellingpartnerapi-na.amazon.com/catalog/2022-04-01/items'
      + '?identifiers=' + encodeURIComponent(chunk.join(','))
      + '&identifiersType=ASIN'
      + '&marketplaceIds=' + encodeURIComponent(mkId)
     + '&includedData=' + encodeURIComponent(INCLUDED)
      + '&pageSize=20';

    let resp;
    if (this.helpers && this.helpers.httpRequest) {
      resp = await this.helpers.httpRequest({ method: 'GET', url: url, headers: { 'x-amz-access-token': token }, json: true });
    } else {
      resp = await this.helpers.request({ method: 'GET', url: url, headers: { 'x-amz-access-token': token }, json: true });
    }
    if (resp && Array.isArray(resp.items)) {
      for (let k = 0; k < resp.items.length; k++) allItems.push(resp.items[k]);
    }
    // Gentle pacing between chunks - stays well inside SP-API rate limits.
    if (i + CHUNK_SIZE < ids.length) {
      await new Promise(function(r) { setTimeout(r, 600); });
    }
  }
  return [{ json: {
    items: allItems,
    numberOfResults: allItems.length,
    chunks_fetched: Math.ceil(ids.length / CHUNK_SIZE),
    identifiers_total: ids.length
  }}];
} catch (err) {
  // Same error shape the validator already handles -> FAMILY_FETCH_FAILED path preserved.
  return [{ json: { error: { message: (err && err.message) ? err.message : String(err) } } }];
}

const sellerRows = $input.first().json;
const sellerRow = Array.isArray(sellerRows) ? sellerRows[0] : sellerRows;
const ctx = $('Validate Input').first().json;

if (!sellerRow) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'SELLER_NOT_FOUND',
    seller_id: ctx.seller_id,
    message: 'No seller record exists for this seller_id.'
  }}];
}

if (sellerRow.status !== 'active') {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'SELLER_NOT_ACTIVE',
    seller_id: ctx.seller_id,
    seller_status: sellerRow.status,
    message: 'This seller account is not active (status: ' + sellerRow.status + '). Access is not permitted.'
  }}];
}

return [{ json: { decision: 'ELIGIBLE' } }];

const status = $input.first().json;
  return [{ json: {
    decision: 'REJECTED',
    reason: 'RATE_LIMITED',
    current_count: status.current_count,
    window_start: status.window_start,
    message: 'This seller has made too many requests to this operation in the current window. Please retry shortly.'
  }}];
